import { mutation } from "./_generated/server";
import type { MutationCtx } from "./_generated/server";
import type { Id } from "./_generated/dataModel";

type Example = {
  title: string;
  description: string;
  code: string;
  explanation: string;
  output?: string;
  difficulty?: "beginner" | "intermediate" | "advanced";
};

type CommonMistake = {
  mistake: string;
  explanation: string;
  howToAvoid: string;
};

type LessonData = {
  title: string;
  type: "theory" | "practice" | "challenge" | "project" | "quiz";
  content: string;
  order: number;
  xpReward?: number;
  estimatedMinutes?: number;
  language?: string;
  codeTemplate?: string;
  solution?: string;
  testCases?: Array<{
    input: string;
    expectedOutput: string;
    isHidden?: boolean;
    description?: string;
    points?: number;
  }>;
  hints?: string[];
  examples?: Example[];
  keyTakeaways?: string[];
  commonMistakes?: CommonMistake[];
  learningObjectives?: string[];
  prerequisites?: string[];
};

type ModuleData = {
  title: string;
  summary?: string;
  lessons: LessonData[];
};

async function createModuleWithLessons(
  ctx: MutationCtx,
  courseId: Id<"courses">,
  module: ModuleData,
  order: number
): Promise<void> {
  const moduleId = await ctx.db.insert("modules", {
    courseId,
    title: module.title,
    order,
    summary: module.summary,
  });
  for (const lesson of module.lessons) {
    await ctx.db.insert("lessons", {
      moduleId,
      courseId,
      title: lesson.title,
      type: lesson.type,
      content: lesson.content,
      order: lesson.order,
      language: lesson.language,
      ...(lesson.codeTemplate && { codeTemplate: lesson.codeTemplate }),
      ...(lesson.solution && { solution: lesson.solution }),
      ...(lesson.testCases && { testCases: lesson.testCases }),
      ...(lesson.hints && { hints: lesson.hints }),
      ...(lesson.xpReward !== undefined && { xpReward: lesson.xpReward }),
      ...(lesson.estimatedMinutes !== undefined && { estimatedMinutes: lesson.estimatedMinutes }),
      ...(lesson.examples && { examples: lesson.examples }),
      ...(lesson.keyTakeaways && { keyTakeaways: lesson.keyTakeaways }),
      ...(lesson.commonMistakes && { commonMistakes: lesson.commonMistakes }),
      ...(lesson.learningObjectives && { notes: { learningObjectives: lesson.learningObjectives, ...(lesson.prerequisites && { prerequisites: lesson.prerequisites }), summary: lesson.content.substring(0, 200) } }),
    });
  }
}


