              code: `type NotificationType = 'success' | 'error' | 'info';

interface Notification {
  id: string;
  type: NotificationType;
  message: string;
}

type NotificationAction =
  | { type: 'ADD'; payload: Notification }
  | { type: 'DISMISS'; payload: string }
  | { type: 'CLEAR_ALL' };

function notificationReducer(state: Notification[], action: NotificationAction): Notification[] {
  switch (action.type) {
    case 'ADD':
      return [...state, action.payload];
    case 'DISMISS':
      return state.filter(n => n.id !== action.payload);
    case 'CLEAR_ALL':
      return [];
    default:
      return state;
  }
}

let nextId = 0;

function NotificationProvider({ children }: { children: React.ReactNode }) {
  const [notifications, dispatch] = useReducer(notificationReducer, []);

  const addNotification = useCallback((type: NotificationType, message: string) => {
    const id = String(++nextId);
    dispatch({ type: 'ADD', payload: { id, type, message } });

    const duration = type === 'error' ? 10000 : 3000;
    setTimeout(() => {
      dispatch({ type: 'DISMISS', payload: id });
    }, duration);
  }, []);

  return (
    <NotificationContext.Provider value={{ notifications, addNotification, dispatch }}>
      {children}
    </NotificationContext.Provider>
  );
}`,
