              code: `type SimpleType = 'string' | 'number' | 'boolean';
type Schema = SimpleType | Record<string, Schema>;

type Infer<T extends Schema> =
  T extends 'string' ? string :
  T extends 'number' ? number :
  T extends 'boolean' ? boolean :
  T extends Record<string, Schema> ? {
    [K in keyof T]: Infer<T[K]>
  } : never;

function validate<T extends Schema>(
  value: unknown,
  schema: T
): value is Infer<T> {
  if (typeof schema === 'string') {
    return typeof value === schema;
  }
  if (typeof value !== 'object' || value === null) return false;
  const obj = value as Record<string, unknown>;
  for (const [key, subSchema] of Object.entries(schema)) {
    if (!(key in obj) || !validate(obj[key], subSchema)) {
      return false;
    }
  }
  return true;
}`,
