              code: `type EventMap = {
  data: [payload: string];
  error: [err: Error];
  close: [];
};

class TypedEmitter<T extends Record<string, any[]>> {
  private listeners = new Map<keyof T, Set<Function>>();

  on<K extends keyof T>(event: K, callback: (...args: T[K]) => void): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(callback);
  }

  emit<K extends keyof T>(event: K, ...args: T[K]): void {
    this.listeners.get(event)?.forEach(cb => cb(...args));
  }

  off<K extends keyof T>(event: K, callback: (...args: T[K]) => void): void {
    this.listeners.get(event)?.delete(callback);
  }
}

const emitter = new TypedEmitter<EventMap>();
emitter.on('data', (payload) => console.log(payload));
emitter.emit('data', 'Hello'); // OK
emitter.emit('data', 42); // Error: 42 is not string`,
