              code: `import { useState, useReducer, useRef, useEffect, useCallback } from "react";

// useState with union type
const [status, setStatus] = useState<"idle" | "loading" | "success" | "error">("idle");
// setStatus("failed"); // Error: not in union

// useReducer with discriminated union
type Action =
  | { type: "increment"; payload: number }
  | { type: "decrement"; payload: number }
  | { type: "reset" };

interface CounterState {
  count: number;
  lastAction: string;
}

function reducer(state: CounterState, action: Action): CounterState {
  switch (action.type) {
    case "increment":
      return { count: state.count + action.payload, lastAction: "increment" };
    case "decrement":
      return { count: state.count - action.payload, lastAction: "decrement" };
    case "reset":
      return { count: 0, lastAction: "reset" };
    default:
      const _exhaustive: never = action;
      return state;
  }
}

// useRef for DOM elements
function TextInput() {
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    inputRef.current?.focus(); // Optional chaining for null
    // inputRef.current.value = "test"; // OK if checked
  }, []);
  return <input ref={inputRef} />;
}

// useRef for mutable values
const renderCount = useRef(0);
renderCount.current += 1; // Mutable

// useCallback with typed parameters
const handleClick = useCallback((event: React.MouseEvent<HTMLButtonElement>) => {
  event.preventDefault();
  console.log("clicked");
}, []);

// Custom hook with explicit return type
function useLocalStorage<T>(key: string, initialValue: T): [T, (value: T | ((prev: T) => T)) => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : initialValue;
    } catch {
      return initialValue;
    }
  });
  const setValue = (value: T | ((prev: T) => T)) => {
    const valueToStore = value instanceof Function ? value(storedValue) : value;
    setStoredValue(valueToStore);
    window.localStorage.setItem(key, JSON.stringify(valueToStore));
  };
  return [storedValue, setValue];
}

// Usage
const [theme, setTheme] = useLocalStorage("theme", "light");
// setTheme("dark") is valid, setTheme(true) is Error`,
