              title: "Typed Auth Context with Custom Hook",
              description: "Complete authentication context with TypeScript",
              code: `import { createContext, useContext, useReducer, ReactNode } from "react";

// Types
interface User {
  id: string;
  email: string;
  name: string;
  role: "admin" | "user" | "viewer";
}

type AuthAction =
  | { type: "LOGIN"; payload: User }
  | { type: "LOGOUT" }
  | { type: "UPDATE_USER"; payload: Partial<User> };

interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

// Context type - no default value
interface AuthContextType {
  state: AuthState;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  updateUser: (updates: Partial<User>) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Reducer
function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case "LOGIN":
      return { ...state, user: action.payload, isAuthenticated: true, isLoading: false };
    case "LOGOUT":
      return { ...state, user: null, isAuthenticated: false, isLoading: false };
    case "UPDATE_USER":
      if (!state.user) return state;
      return { ...state, user: { ...state.user, ...action.payload } };
    default:
      return state;
  }
}

// Provider
function AuthProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(authReducer, {
    user: null,
    isAuthenticated: false,
    isLoading: true,
  });

  const login = async (email: string, password: string) => {
    const user: User = await api.login(email, password);
    dispatch({ type: "LOGIN", payload: user });
  };

  const logout = () => dispatch({ type: "LOGOUT" });

  const updateUser = (updates: Partial<User>) => {
    dispatch({ type: "UPDATE_USER", payload: updates });
  };

  return (
    <AuthContext.Provider value={{ state, login, logout, updateUser }}>
      {children}
    </AuthContext.Provider>
  );
}

// Custom hook with null check
function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

// Usage in components
function Profile() {
  const { state: { user }, updateUser } = useAuth();
  if (!user) return <Login />;
  return <div>Welcome, {user.name}</div>;
}

export { AuthProvider, useAuth };`,
              explanation: "AuthContextType defines the full API. createContext with undefined default forces the custom hook to check for undefined. The authReducer handles login, logout, and update actions. useAuth provides a typed shortcut that throws if used outside the provider.",
