              code: `import { ElementType, ComponentPropsWithoutRef, forwardRef } from "react";

// Type map for element props
type PolymorphicProps<T extends ElementType> = {
  as?: T;
  children?: React.ReactNode;
} & ComponentPropsWithoutRef<T>;

function PolymorphicBox<T extends ElementType = "div">(
  { as, children, ...props }: PolymorphicProps<T>,
  ref: React.Ref<HTMLElement>
) {
  const Component = as || "div";
  return (
    <Component ref={ref} {...props}>
      {children}
    </Component>
  );
}

const Box = forwardRef(PolymorphicBox) as <T extends ElementType = "div">(
  props: PolymorphicProps<T> & { ref?: React.Ref<HTMLElement> }
) => React.ReactElement;

// Usage
<Box as="button" onClick={() => console.log("click")}>Click</Box>
<Box as="a" href="https://example.com">Link</Box>
<Box as="h1" style={{ color: "red" }}>Heading</Box>
// TypeScript validates props based on the as element type`,
