          solution: `@RestController
@RequestMapping("/api/tasks")
public class TaskController {
    private final ConcurrentHashMap<Long, Task> tasks = new ConcurrentHashMap<>();
    private final AtomicLong idCounter = new AtomicLong(1);

    @GetMapping
    public List<Task> getAll() {
        return new ArrayList<>(tasks.values());
    }

    @GetMapping("/{id}")
    public Task getById(@PathVariable Long id) {
        Task task = tasks.get(id);
        if (task == null) throw new ResponseStatusException(HttpStatus.NOT_FOUND);
        return task;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public Task create(@RequestBody Task task) {
        Long id = idCounter.getAndIncrement();
        task.setId(id);
        tasks.put(id, task);
        return task;
    }

    @PutMapping("/{id}")
    public Task update(@PathVariable Long id, @RequestBody Task task) {
        if (!tasks.containsKey(id)) throw new ResponseStatusException(HttpStatus.NOT_FOUND);
        task.setId(id);
        tasks.put(id, task);
        return task;
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void delete(@PathVariable Long id) {
        if (tasks.remove(id) == null) throw new ResponseStatusException(HttpStatus.NOT_FOUND);
    }
}
`,
