          solution: `// ProductResponse DTO
public record ProductResponse(Long id, String name, String description, double price, int quantity, String category, String stockStatus, LocalDateTime createdAt) {}

// ProductRequest DTO  
public record ProductRequest(@NotBlank @Size(min = 2, max = 100) String name, String description, @Positive double price, @Min(0) int quantity, String category) {}

// ProductService
@Service
public class ProductService {
    private final ConcurrentHashMap<Long, Product> store = new ConcurrentHashMap<>();
    private final AtomicLong idGen = new AtomicLong(1);

    public List<Product> findAll(String category) {
        return store.values().stream()
            .filter(p -> category == null || p.getCategory().equalsIgnoreCase(category))
            .toList();
    }

    public Optional<Product> findById(Long id) { return Optional.ofNullable(store.get(id)); }

    public Product create(ProductRequest req) {
        Product p = new Product(idGen.getAndIncrement(), req.name(), req.description(), req.price(), req.quantity(), req.category(), LocalDateTime.now());
        store.put(p.getId(), p);
        return p;
    }

    public Product update(Long id, ProductRequest req) {
        Product existing = store.get(id);
        if (existing == null) throw new NoSuchElementException("Product not found: " + id);
        Product updated = new Product(id, req.name(), req.description(), req.price(), req.quantity(), req.category(), existing.getCreatedAt());
        store.put(id, updated);
        return updated;
    }

    public void delete(Long id) { if (store.remove(id) == null) throw new NoSuchElementException("Product not found: " + id); }
}

// ProductController
@RestController
@RequestMapping("/api/products")
public class ProductController {
    @Autowired private ProductService service;
    @Autowired private ProductMapper mapper;

    @GetMapping
    public ResponseEntity<List<ProductResponse>> getAll(@RequestParam(required = false) String category) {
        return ResponseEntity.ok(mapper.toResponseList(service.findAll(category)));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ProductResponse> getById(@PathVariable Long id) {
        return service.findById(id).map(p -> ResponseEntity.ok(mapper.toResponse(p))).orElse(ResponseEntity.notFound().build());
    }

    @PostMapping
    public ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest req) {
        Product created = service.create(req);
        return ResponseEntity.created(URI.create("/api/products/" + created.getId())).body(mapper.toResponse(created));
    }

    @PutMapping("/{id}")
    public ResponseEntity<ProductResponse> update(@PathVariable Long id, @Valid @RequestBody ProductRequest req) {
        Product updated = service.update(id, req);
        return ResponseEntity.ok(mapper.toResponse(updated));
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable Long id) {
        service.delete(id);
        return ResponseEntity.noContent().build();
    }
}

// GlobalExceptionHandler
@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(NOT_FOUND)
    public Map<String, String> handleNotFound(NoSuchElementException ex) {
        return Map.of("error", "Not Found", "message", ex.getMessage());
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(BAD_REQUEST)
    public Map<String, Object> handleValidation(MethodArgumentNotValidException ex) {
        List<String> errors = ex.getBindingResult().getFieldErrors().stream()
            .map(e -> e.getField() + ": " + e.getDefaultMessage()).toList();
        return Map.of("error", "Validation Failed", "details", errors);
    }
}`,
