          commonMistakes: [{ mistake: "Forgetting int.Parse for numeric input", explanation: "Console.ReadLine returns string.", howToAvoid: "Use int.Parse or int.TryParse for numbers." }, { mistake: "Missing using System;", explanation: "Console requires System namespace.", howToAvoid: "Include using System; at top." }],
