              code: `const OpenAPIDiff = require('openapi-diff');

// Compare two OpenAPI specs to detect breaking changes
async function detectBreakingChanges(oldSpec, newSpec) {
  const diff = await OpenAPIDiff.diffSpecs({
    sourceSpec: { content: oldSpec, format: 'openapi3' },
    destinationSpec: { content: newSpec, format: 'openapi3' },
  });
  
  const breakingChanges = diff.filter(
    change => change.type === 'breaking'
  );
  
  return {
    hasBreakingChanges: breakingChanges.length > 0,
    changes: {
      breaking: breakingChanges,
      nonBreaking: diff.filter(c => c.type !== 'breaking'),
    },
    autoMigrationSteps: breakingChanges.map(c => ({
      what: c.message,
      severity: c.severity,
      migrationGuide: generateMigrationStep(c),
    })),
  };
}

// CI/CD usage:
// 1. Compare current spec against deployed spec
// 2. If breaking changes found, require MAJOR version bump
// 3. Auto-generate migration guide from diff`,
