export const seedPopulateAll = mutation({
  args: {},
  handler: async (ctx) => {
    const results: Record<string, string> = {};

    // Step 1: Clean up duplicate/enhanced courses
    const allCourses = await ctx.db.query("courses").collect();
    for (const course of allCourses) {
      if (course.slug && DUPLICATE_SLUGS.has(course.slug)) {
        await deleteCourseWithContent(ctx, course._id);
        results[course.slug] = "Removed (duplicate/enhanced)";
      }
    }

    // Step 2: Create missing canonical courses
    const updatedCourses = await ctx.db.query("courses").collect();
    for (const courseDef of CANONICAL_COURSES) {
      const exists = updatedCourses.some((c) => c.slug === courseDef.slug);
      if (!exists) {
        await ctx.db.insert("courses", {
          ...courseDef,
          totalLessons: 0,
          isPublished: true,
        });
        results[courseDef.slug] = "Created";
      }
    }

    // Step 3: Populate content for courses with empty modules
    const finalCourses = await ctx.db.query("courses").collect();
    for (const course of finalCourses) {
      if (!course.slug) continue;
      const existingModules = await ctx.db
        .query("modules")
        .withIndex("by_course", (q) => q.eq("courseId", course._id))
        .collect();

      if (existingModules.length > 0) {
        continue;
      }

      switch (course.slug) {
        case "html-css":
          await seedMinimalHtmlCss(ctx, course._id);
          results[course.slug] = "Populated with HTML & CSS content (4 modules, ~14 lessons)";
          break;
        case "go":
          await seedMinimalGo(ctx, course._id);
          results[course.slug] = "Populated with Go content (4 modules, ~14 lessons)";
          break;
        case "rust":
          await seedMinimalRust(ctx, course._id);
          results[course.slug] = "Populated with Rust content (3 modules, ~8 lessons)";
          break;
        case "dotnet":
          await seedMinimalDotNet(ctx, course._id);
          results[course.slug] = "Populated with .NET content (3 modules, ~8 lessons)";
          break;
        case "api-development":
          await seedMinimalApiDev(ctx, course._id);
          results[course.slug] = "Populated with API Dev content (3 modules, ~8 lessons)";
          break;
        case "python":
          await seedPythonContent(ctx, course._id);
          results[course.slug] = "Populated with Python content (5 modules, ~13 lessons)";
          break;
        case "javascript":
          await seedJavaScriptContent(ctx, course._id);
          results[course.slug] = "Populated with JavaScript content (2 modules, ~6 lessons)";
          break;
        case "react":
          await seedReactContent(ctx, course._id);
          results[course.slug] = "Populated with React content (4 modules, ~20 lessons)";
          break;
        case "typescript":
          await seedTypeScriptContent(ctx, course._id);
          results[course.slug] = "Populated with TypeScript content (8 modules, ~40 lessons)";
          break;
        case "spring-boot":
          await seedSpringBootContent(ctx, course._id);
          results[course.slug] = "Populated with Spring Boot content (10 modules, ~50 lessons)";
          break;
        default:
          results[course.slug] = "Skipped (no content defined for this slug)";
      }
    }

    const totalFixed = Object.values(results).filter((v) => v.startsWith("Populated")).length;

    return {
      message: `Seed complete. Fixed ${totalFixed} empty courses.`,
      details: results,
    };
  },
});







